interface PeruMapProps {
  className?: string
  datosRegionales?: {
    [key: string]: {
      nna1: number
      nna3: number
      nna5: number
      tasaRetencion: number
    }
  }
}

export function PeruMap({ className = 'w-full h-auto max-h-[300px]', datosRegionales }: PeruMapProps) {
  const [hovered, setHovered] = useState<string | null>(null)

  const getColor = (name: string) => {
    const upper = name.toUpperCase()
    if (upper === 'LORETO') return '#1e293b'
    if (upper === 'UCAYALI') return '#0369a1'
    if (upper === 'PUNO') return '#0284c7'
    return '#e2e8f0'
  }

  const getStroke = (name: string) => {
    const upper = name.toUpperCase()
    if (upper === 'LORETO') return '#0f172a'
    if (upper === 'UCAYALI') return '#075985'
    if (upper === 'PUNO') return '#0369a1'
    return '#cbd5e1'
  }

  return (
    <div className="relative flex flex-col items-center select-none">
      <svg viewBox="0 0 250 340" className={className}>
        <defs>
          <filter id="shadow" x="-5%" y="-5%" width="110%" height="110%">
            <feDropShadow dx="0" dy="1" stdDeviation="1" floodOpacity="0.15" />
          </filter>
        </defs>

        {DEPARTAMENTOS.map((dep) => {
          const isLoreto = dep.name === 'LORETO'
          const isUcayali = dep.name === 'UCAYALI'
          const isPuno = dep.name === 'PUNO'
          const isTarget = isLoreto || isUcayali || isPuno
          const isHovered = hovered === dep.name

          return (
            <path
              key={dep.name}
              d={dep.d}
              fill={getColor(dep.name)}
              stroke={getStroke(dep.name)}
              strokeWidth={isTarget ? 1.2 : 0.8}
              className={`transition-all duration-150 ${isTarget ? 'cursor-pointer hover:opacity-90' : 'opacity-70'}`}
              onMouseEnter={() => setHovered(dep.name)}
              onMouseLeave={() => setHovered(null)}
              style={{
                filter: isTarget ? 'drop-shadow(0px 1px 2px rgba(0,0,0,0.2))' : undefined,
                transform: isHovered && isTarget ? 'scale(1.01)' : undefined,
                transformOrigin: 'center center',
              }}
            >
              <title>{dep.name}</title>
            </path>
          )
        })}

        {/* Callout Loreto */}
        <g transform="translate(130, 80)" className="pointer-events-none">
          <circle cx="0" cy="0" r="2.5" fill="#38bdf8" />
          <line x1="0" y1="0" x2="32" y2="-12" stroke="#0284c7" strokeWidth="1" strokeDasharray="2,2" />
          <rect x="34" y="-22" width="72" height="20" rx="3" fill="#1e293b" opacity="0.95" />
          <text x="38" y="-12" fill="#ffffff" fontSize="6.5" fontWeight="bold">LORETO</text>
          <text x="38" y="-5" fill="#38bdf8" fontSize="6" fontFamily="monospace">
            {datosRegionales?.LORETO ? `${datosRegionales.LORETO.tasaRetencion}% (3S)` : '55.5% (3S)'}
          </text>
        </g>

        {/* Callout Ucayali */}
        <g transform="translate(145, 175)" className="pointer-events-none">
          <circle cx="0" cy="0" r="2.5" fill="#38bdf8" />
          <line x1="0" y1="0" x2="28" y2="-8" stroke="#0284c7" strokeWidth="1" strokeDasharray="2,2" />
          <rect x="30" y="-18" width="74" height="20" rx="3" fill="#0369a1" opacity="0.95" />
          <text x="34" y="-8" fill="#ffffff" fontSize="6.5" fontWeight="bold">UCAYALI</text>
          <text x="34" y="-1" fill="#bae6fd" fontSize="6" fontFamily="monospace">
            {datosRegionales?.UCAYALI ? `${datosRegionales.UCAYALI.tasaRetencion}% (3S)` : '70.1% (3S)'}
          </text>
        </g>

        {/* Callout Puno */}
        <g transform="translate(205, 275)" className="pointer-events-none">
          <circle cx="0" cy="0" r="2.5" fill="#38bdf8" />
          <line x1="0" y1="0" x2="20" y2="12" stroke="#0284c7" strokeWidth="1" strokeDasharray="2,2" />
          <rect x="18" y="14" width="60" height="20" rx="3" fill="#0284c7" opacity="0.95" />
          <text x="22" y="24" fill="#ffffff" fontSize="6.5" fontWeight="bold">PUNO</text>
          <text x="22" y="31" fill="#e0f2fe" fontSize="6" fontFamily="monospace">
            {datosRegionales?.PUNO ? `${datosRegionales.PUNO.tasaRetencion}% (3S)` : '22.6% (3S)'}
          </text>
        </g>
      </svg>

      {/* Leyenda inferior del mapa */}
      <div className="flex items-center gap-3 text-[10px] text-slate-500 mt-1">
        <span className="flex items-center gap-1 font-medium">
          <span className="w-2.5 h-2.5 rounded-sm bg-[#1e293b] inline-block"></span> Loreto
        </span>
        <span className="flex items-center gap-1 font-medium">
          <span className="w-2.5 h-2.5 rounded-sm bg-[#0369a1] inline-block"></span> Ucayali
        </span>
        <span className="flex items-center gap-1 font-medium">
          <span className="w-2.5 h-2.5 rounded-sm bg-[#0284c7] inline-block"></span> Puno
        </span>
      </div>
    </div>
  )
}
